import sys

data = sys.stdin.read().split()
n, s = int(data[0]), int(data[1])
pos = 2
conf = [[False] * n for _ in range(n)]
for _ in range(s):
    k = int(data[pos])
    cs = [int(x) for x in data[pos + 1:pos + 1 + k]]
    pos += 1 + k
    for a in cs:
        for b in cs:
            if a != b:
                conf[a][b] = True

def colorable(k):
    col = [-1] * n
    def go(v, used):
        if v == n:
            return True
        for c in range(min(k, used + 1)):
            if all(not (conf[v][u] and col[u] == c) for u in range(v)):
                col[v] = c
                if go(v + 1, max(used, c + 1)):
                    return True
                col[v] = -1
        return False
    return go(0, 0)

k = 1
while not colorable(k):
    k += 1
print(k)

